package com.nephh.business;
import com.nephh.common.ApiResponse;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import static com.nephh.business.AccessService.*;

@RestController @RequestMapping("/api/business/patrol")
public class PatrolController {
 private final JdbcTemplate db;private final AccessService access;
 public PatrolController(JdbcTemplate db,AccessService access){this.db=db;this.access=access;}
 @GetMapping("/plans") public ApiResponse<?> plans(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);access.manager(a);String sql="select p.*,a.name area_name,u.username assignee_name from patrol_plan p join area a on a.id=p.area_id join sys_user u on u.id=p.assignee_id";return ApiResponse.ok(a.role().equals("ADMIN")?db.queryForList(sql+" order by p.id desc"):db.queryForList(sql+" join user_area ua on ua.area_id=p.area_id where ua.user_id=? order by p.id desc",a.id()));}
 @PostMapping("/plans") @Transactional public ApiResponse<?> create(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);long area=number(b,"areaId"),user=number(b,"assigneeId");access.area(a,area);var target=access.one("select * from sys_user where id=? and enabled=true",user);if(!target.get("role_code").equals("INSPECTOR")||db.queryForObject("select count(*) from user_area where user_id=? and area_id=?",Integer.class,user,area)==0)bad("执行人必须为该区域的巡检员");int period=(int)number(b,"periodHours");if(period<1||period>8760)bad("巡检周期应在1至8760小时之间");if(!(b.get("points") instanceof List<?>))bad("请添加巡检点");List<?> points=(List<?>)b.get("points");if(points.isEmpty())bad("至少添加一个巡检点");String name=text(b,"name",200);long id=access.insert("insert into patrol_plan(name,area_id,assignee_id,period_hours) values(?,?,?,?)",name,area,user,period);for(Object point:points){if(!(point instanceof Map<?,?>))bad("巡检点格式不正确");@SuppressWarnings("unchecked") Map<String,Object> p=(Map<String,Object>)point;long nodeId=number(p,"nodeId");var node=access.node(a,nodeId);if(((Number)node.get("area_id")).longValue()!=area)bad("巡检点必须属于该区域");db.update("insert into patrol_plan_point(plan_id,node_id,check_items) values(?,?,?)",id,nodeId,text(p,"checkItems",2000));}access.audit(a,"CREATE","PATROL_PLAN",id,null,name);return ApiResponse.ok(Map.of("id",id));}
 @PostMapping("/plans/{id}/enabled") public ApiResponse<?> enable(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);var plan=access.one("select * from patrol_plan where id=?",id);access.area(a,((Number)plan.get("area_id")).longValue());db.update("update patrol_plan set enabled=? where id=?",Boolean.TRUE.equals(b.get("enabled")),id);access.audit(a,"TOGGLE","PATROL_PLAN",id,plan.get("enabled"),b.get("enabled"));return ApiResponse.ok(null);}
 @PostMapping("/plans/{id}/generate") @Transactional public ApiResponse<?> generate(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);access.manager(a);var plan=access.one("select * from patrol_plan where id=?",id);access.area(a,((Number)plan.get("area_id")).longValue());long run=generateRun(id);access.audit(a,"GENERATE","PATROL_RUN",run,null,id);return ApiResponse.ok(Map.of("id",run));}
 @Transactional public long generateRun(long planId){var rows=db.queryForList("select p.* from patrol_plan p join sys_user u on u.id=p.assignee_id where p.id=? and p.enabled=true and u.enabled=true for update",planId);if(rows.isEmpty())bad("计划或执行人已停用");var plan=rows.get(0);long run=access.insert("insert into patrol_run(plan_id,assignee_id) values(?,?)",planId,plan.get("assignee_id"));db.update("insert into patrol_result(run_id,node_id,check_items) select ?,node_id,check_items from patrol_plan_point where plan_id=?",run,planId);db.update("update patrol_plan set next_run=? where id=?",Timestamp.from(Instant.now().plusSeconds(((Number)plan.get("period_hours")).longValue()*3600)),planId);access.notify(((Number)plan.get("assignee_id")).longValue(),"新巡检任务",plan.get("name").toString(),"PATROL",run);return run;}
 @GetMapping("/runs") public ApiResponse<?> runs(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);String sql="select r.*,p.name,p.area_id,u.username assignee_name from patrol_run r join patrol_plan p on p.id=r.plan_id join sys_user u on u.id=r.assignee_id";return ApiResponse.ok(a.role().equals("ADMIN")?db.queryForList(sql+" order by r.id desc limit 300"):a.manager()?db.queryForList(sql+" join user_area ua on ua.area_id=p.area_id where ua.user_id=? order by r.id desc limit 300",a.id()):db.queryForList(sql+" join user_area ua on ua.area_id=p.area_id where ua.user_id=? and r.assignee_id=? order by r.id desc limit 300",a.id(),a.id()));}
 @Transactional public void generateDueRun(long id){var plans=db.queryForList("select id from patrol_plan where id=? and enabled=true and next_run<=CURRENT_TIMESTAMP for update",id);if(!plans.isEmpty())generateRun(id);}
 @GetMapping("/runs/{id}") public ApiResponse<?> run(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);var run=checkRun(a,id);var points=db.queryForList("select r.*,n.code,n.location from patrol_result r join monitoring_node n on n.id=r.node_id where r.run_id=? order by r.id",id);for(var point:points)point.put("attachments",db.queryForList("select id,original_name,content_type from patrol_attachment where result_id=?",point.get("id")));run.put("points",points);return ApiResponse.ok(run);}
 private Map<String,Object> checkRun(Actor a,long id){var run=access.one("select r.*,p.area_id,p.name from patrol_run r join patrol_plan p on p.id=r.plan_id where r.id=?",id);access.area(a,((Number)run.get("area_id")).longValue());if(!a.manager()&&!Objects.equals(run.get("assignee_id"),a.id()))deny();return run;}
 @PostMapping("/results/{id}") @Transactional public ApiResponse<?> result(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);var point=access.one("select * from patrol_result where id=? for update",id);long runId=((Number)point.get("run_id")).longValue();var run=checkRun(a,runId);if(!Objects.equals(run.get("assignee_id"),a.id()))deny();if(point.get("checked_at")!=null)bad("该点位已提交");String result=text(b,"result",4000);boolean abnormal=Boolean.TRUE.equals(b.get("abnormal"));Long order=null;if(abnormal){order=access.insert("insert into work_order(node_id,title,priority,creator_id,description) values(?,?,'MEDIUM',?,?)",point.get("node_id"),"巡检异常："+run.get("name"),a.id(),result);db.update("insert into order_event(order_id,actor_id,action,note) values(?,?,'CREATE',?)",order,a.id(),"巡检异常自动转工单");}db.update("update patrol_result set result_text=?,abnormal=?,checked_at=CURRENT_TIMESTAMP,order_id=? where id=?",result,abnormal,order,id);if(db.queryForObject("select count(*) from patrol_result where run_id=? and checked_at is null",Integer.class,runId)==0)db.update("update patrol_run set status='COMPLETED',completed_at=CURRENT_TIMESTAMP where id=?",runId);else db.update("update patrol_run set status='PROCESSING' where id=?",runId);access.audit(a,"CHECK","PATROL_POINT",id,null,result);return ApiResponse.ok(null);}
}
